import { homedir } from "node:os";
import { dirname, join } from "node:path";
function getDefaultOpenCodeConfigDir() {
  const userConfigDir = process.env.XDG_CONFIG_HOME ? process.env.XDG_CONFIG_HOME : join(homedir(), ".config");
  return join(userConfigDir, "opencode");
}
function getCustomOpenCodeConfigDir() {
  const configDir = process.env.OPENCODE_CONFIG_DIR?.trim();
  return configDir || undefined;
}
function getCustomTuiConfigPath() {
  const configPath = process.env.OPENCODE_TUI_CONFIG?.trim();
  return configPath || undefined;
}
function getConfigDir() {
  const customConfigDir = getCustomOpenCodeConfigDir();
  if (customConfigDir) {
    return customConfigDir;
  }
  return getDefaultOpenCodeConfigDir();
}
function getConfigSearchDirs() {
  const dirs = [getCustomOpenCodeConfigDir(), getDefaultOpenCodeConfigDir()];
  return dirs.filter((dir, index) => {
    return Boolean(dir) && dirs.indexOf(dir) === index;
  });
}
function getOpenCodeConfigPaths() {
  const configDir = getConfigDir();
  return [join(configDir, "opencode.json"), join(configDir, "opencode.jsonc")];
}
function getTuiConfig() {
  const customConfigPath = getCustomTuiConfigPath();
  if (customConfigPath)
    return customConfigPath;
  return join(getConfigDir(), "tui.json");
}
function getTuiConfigJsonc() {
  return join(getConfigDir(), "tui.jsonc");
}

// src/cli/skills.ts
var PERMISSION_ONLY_SKILLS = [
  {
    name: "requesting-code-review",
    allowedAgents: ["oracle"],
    description: "Code review template for reviewer subagents in multi-step workflows"
  }
];
function getSkillPermissionsForAgent(agentName, skillList, disabledSkillNames) {
  const disabledSkills = new Set(Array.isArray(disabledSkillNames) ? disabledSkillNames : []);
  const permissions = {
    "*": agentName === "orchestrator" ? "allow" : "deny"
  };
  if (skillList) {
    permissions["*"] = "deny";
    for (const name of skillList) {
      if (name === "*") {
        permissions["*"] = "allow";
      } else if (name.startsWith("!")) {
        permissions[name.slice(1)] = "deny";
      } else if (!disabledSkills.has(name)) {
        permissions[name] = "allow";
      }
    }
    for (const name of disabledSkills) {
      permissions[name] = "deny";
    }
    return permissions;
  }
  for (const skill of CUSTOM_SKILLS) {
    const isAllowed = skill.allowedAgents.includes("*") || skill.allowedAgents.includes(agentName);
    if (isAllowed && !disabledSkills.has(skill.name)) {
      permissions[skill.name] = "allow";
    }
  }
  for (const skill of PERMISSION_ONLY_SKILLS) {
    const isAllowed = skill.allowedAgents.includes("*") || skill.allowedAgents.includes(agentName);
    if (isAllowed && !disabledSkills.has(skill.name)) {
      permissions[skill.name] = "allow";
    }
  }
  for (const name of disabledSkills) {
    permissions[name] = "deny";
  }
  return permissions;
}

