// src/agents/council-agents.ts
var COUNCILLOR_AGENT_PREFIX = "councillor-";
function buildCouncillorAgents(runtime, disabled) {
  const council = runtime.council;
  if (!council)
    return [];
  const presetName = council.default_preset ?? "default";
  const preset = council.presets[presetName];
  if (!preset)
    return [];
  const agents = [];
  for (const [name, cfg] of Object.entries(preset)) {
    if (name === "master")
      continue;
    const agentName = `${COUNCILLOR_AGENT_PREFIX}${name}`;
    if (disabled.has(agentName))
      continue;
    const base = createCouncillorAgent(cfg.model, undefined, cfg.prompt, cfg.variant);
    if (cfg.models.length > 1) {
      base._modelArray = cfg.models;
      base.config.model = undefined;
    }
    agents.push({ ...base, name: agentName });
  }
  return agents;
}
function getCouncillorSeatName(agentName) {
  return agentName.startsWith(COUNCILLOR_AGENT_PREFIX) ? agentName.slice(COUNCILLOR_AGENT_PREFIX.length) : agentName;
}

