// src/utils/logger.ts
import * as fs2 from "node:fs";
import { appendFile } from "node:fs/promises";
import * as os from "node:os";
import * as path3 from "node:path";
var LOG_PREFIX = "oh-my-opencode-slim.";
var LOG_SUFFIX = ".log";
var RETENTION_MS = 7 * 24 * 60 * 60 * 1000;
var FALLBACK_WARNING = "[oh-my-opencode-slim] file logging unavailable, falling back to stderr";
var loggerGeneration = 0;
var currentSink = { kind: "uninitialized" };
var writeChain = Promise.resolve();
function getLogDir() {
  return process.env.OPENCODE_LOG_DIR ?? path3.join(os.homedir(), ".local/share/opencode/log");
}
function cleanupOldLogs(logDir) {
  try {
    const entries = fs2.readdirSync(logDir);
    const now = Date.now();
    for (const entry of entries) {
      if (entry.startsWith(LOG_PREFIX) && entry.endsWith(LOG_SUFFIX)) {
        const filePath = path3.join(logDir, entry);
        try {
          const stat = fs2.statSync(filePath);
          if (now - stat.mtimeMs > RETENTION_MS) {
            fs2.unlinkSync(filePath);
          }
        } catch {}
      }
    }
  } catch {}
  try {
    const bgTaskDir = path3.join(logDir, "bg-tasks");
    const taskFiles = fs2.readdirSync(bgTaskDir);
    const now = Date.now();
    for (const entry of taskFiles) {
      if (!entry.endsWith(".json"))
        continue;
      const filePath = path3.join(bgTaskDir, entry);
      try {
        const stat = fs2.statSync(filePath);
        if (now - stat.mtimeMs > RETENTION_MS) {
          fs2.unlinkSync(filePath);
        }
      } catch {}
    }
  } catch {}
}
function safeStderr(message) {
  try {
    console.error(message);
  } catch {}
}
function enterStderrFallback(expectedGeneration) {
  if (expectedGeneration !== loggerGeneration)
    return;
  if (currentSink.kind === "stderr")
    return;
  currentSink = { kind: "stderr" };
  safeStderr(FALLBACK_WARNING);
}
function handleAppendFailure(failedGeneration, logEntry) {
  enterStderrFallback(failedGeneration);
  safeStderr(logEntry.trimEnd());
}
function initLogger(sessionId) {
  const attemptGeneration = ++loggerGeneration;
  try {
    const dir = getLogDir();
    fs2.mkdirSync(dir, { recursive: true });
    const nextLogFile = path3.join(dir, `${LOG_PREFIX}${sessionId}${LOG_SUFFIX}`);
    fs2.closeSync(fs2.openSync(nextLogFile, "a"));
    if (attemptGeneration !== loggerGeneration)
      return;
    currentSink = {
      kind: "file",
      filePath: nextLogFile
    };
    cleanupOldLogs(dir);
  } catch {
    enterStderrFallback(attemptGeneration);
  }
}
function log(message, data) {
  try {
    const sink = currentSink;
    const entryGeneration = loggerGeneration;
    if (sink.kind === "uninitialized")
      return;
    const timestamp = new Date().toISOString();
    let dataStr = "";
    if (data !== undefined) {
      try {
        dataStr = JSON.stringify(data);
      } catch {
        dataStr = "[unserializable]";
      }
    }
    const logEntry = `[${timestamp}] ${message} ${dataStr}
`;
    if (sink.kind === "stderr") {
      safeStderr(logEntry.trimEnd());
      return;
    }
    const filePath = sink.filePath;
    writeChain = writeChain.catch(() => {
      return;
    }).then(async () => {
      if (entryGeneration === loggerGeneration && currentSink.kind === "stderr") {
        safeStderr(logEntry.trimEnd());
        return;
      }
      try {
        await appendFile(filePath, logEntry);
      } catch {
        handleAppendFailure(entryGeneration, logEntry);
      }
    }).catch(() => {
      return;
    });
  } catch {}
}

