    const activePaths = new Set([...interviewsById.values()].filter((i) => i.status === "active").map((i) => path17.resolve(i.markdownPath)));
    let entries;
    try {
      entries = await fs8.readdir(outputDir);
    } catch {
      return [];
    }
    const items = [];
    for (const entry of entries) {
      if (!entry.endsWith(".md"))
        continue;
      const fullPath = path17.join(outputDir, entry);
      if (activePaths.has(path17.resolve(fullPath)))
        continue;
      let content;
      try {
        content = await fs8.readFile(fullPath, "utf8");
      } catch {
        continue;
      }
      const title = extractTitle(content) || entry.replace(/\.md$/, "");
      const summary = extractSummarySection(content) || "";
      const baseName = entry.replace(/\.md$/, "");
      items.push({
        fileName: entry,
        resumeCommand: `/interview ${baseName}`,
        title,
        summary: summary.length > 120 ? `${summary.slice(0, 120)}…` : summary
      });
    }
    const sorted = items.sort((a, b) => a.title.localeCompare(b.title));
    fileCache = { items: sorted, at: Date.now() };
    return sorted;
