        const interviewId = service.getActiveInterviewId(sessionID);
        if (!interviewId)
          continue;
        pollPendingAnswers(sessionID).catch(() => {});
        pollNudgeAction(sessionID).catch(() => {});
        pollBlockComment(sessionID).catch(() => {});
        pollChat(sessionID).catch(() => {});
